package net.minecraft.util.math; import net.minecraft.util.EnumFacing; public final class BlockPos { public final int x,y,z; public BlockPos(int x,int y,int z){this.x=x;this.y=y;this.z=z;} public BlockPos offset(EnumFacing f){return new BlockPos(x+f.x,y+f.y,z+f.z);} @Override public boolean equals(Object o){if(!(o instanceof BlockPos))return false; BlockPos p=(BlockPos)o;return x==p.x&&y==p.y&&z==p.z;} @Override public int hashCode(){return (x*31+y)*31+z;} @Override public String toString(){return x+","+y+","+z;} }
